def run(*a):
    try:
        return subprocess.run(DRIVE + [str(x) for x in a], cwd=os.environ.get("ROOT", "."),
                              capture_output=True, text=True, timeout=45)
    except subprocess.TimeoutExpired:
        class R: returncode = 1; stdout = ""; stderr = "timeout"
        return R()


def dump():
    p = tempfile.mktemp(suffix=".json")
    r = run("ui", "--filter", "", "--save", p)
    if r.returncode:
        sys.exit("ui failed: " + r.stderr[-300:])
    d = json.load(open(p)); os.unlink(p)
    return [c for c in d["controls"] if c.get("rect") and c["rect"][2] > 0 and c["rect"][3] > 0 and c.get("visible")]


def find(name, classes=None, field="name"):
    cs = dump()
    if classes:
        cs = [c for c in cs if c.get("class") in classes]
    order = {"name": ("name", "text", "tooltip"), "text": ("text", "name", "tooltip"),
             "tooltip": ("tooltip", "name", "text")}[field]
    for key in order:
        hits = [c for c in cs if c.get(key) == name]
        if hits:
            return hits[0]
    sys.exit("control not found: " + name)


def center(c):
    x, y, w, h = c["rect"]
